 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != background and color == grid[r][c + 1] and grid[r][c] == background:
                out[r][c] = 2
    return out
